const pageData = await browserjs(tabId, () => {
  // Let's find all school cards/containers
  const results = [];
  // US News usually puts cards in articles or divs with specific testids
  const cards = document.querySelectorAll('div[class*="Card__"], div[class*="DetailCard"]');

  // Let's find all h3s that have school names
  const h3s = Array.from(document.querySelectorAll('h3')).filter(h => {
    return h.querySelector('a') && h.innerText.trim().length > 0;
  });

  for (const h of h3s) {
    const a = h.querySelector('a');
    const name = a ? a.innerText.trim() : h.innerText.trim();
    const href = a ? a.href : '';

    // Look at parent or siblings for rank, location
    let container = h.closest('div[class*="Card"]') || h.parentElement.parentElement;
    let text = container ? container.innerText : '';
    results.push({ name, href, text: text.slice(0, 300) });
  }

  return {
    h3Count: h3s.length,
    results: results.slice(0, 25)
  };
});

