const inspection = await browserjs(tabId, () => {
  // Let's find all links matching top-law-schools
  const links = Array.from(document.querySelectorAll('a[href*="/best-graduate-schools/top-law-schools/"]'));
  const uniqueSchools = [];
  const seen = new Set();
  for (const a of links) {
    const text = a.innerText.trim();
    const href = a.href;
    if (href.match(/\/top-law-schools\/[a-z0-9-]+-[0-9]+/i) && !href.includes('?photo-strip') && !href.includes('#reviews')) {
      if (!seen.has(href)) {
        seen.add(href);
        // Find parent container text
        let p = a;
        for (let i = 0; i < 5; i++) {
          if (p.parentElement) p = p.parentElement;
        }
        uniqueSchools.push({
          text,
          href,
          containerSnippet: p.innerText.slice(0, 200).replace(/\n+/g, ' | ')
        });
      }
    }
  }
  return uniqueSchools;
});

