// Now let's extract all schools and their location/rank
const schools = await browserjs(tabId, () => {
  // Let's find all cards or articles
  // In US News, cards typically contain rank, school name, city, state
  const items = [];

  // Find all links to school profiles
  const links = Array.from(document.querySelectorAll('a[href*="/best-graduate-schools/top-law-schools/"]'));
  const seen = new Set();

  for (const a of links) {
    const href = a.href;
    if (href.match(/\/top-law-schools\/[a-z0-9-]+-[0-9]+$/i)) {
      if (!seen.has(href)) {
        seen.add(href);

        // Find container text to extract rank and city/state
        let container = a.closest('div[class*="Card"]') || a.parentElement;
        while (container && container.innerText.length < 50 && container.parentElement) {
          container = container.parentElement;
        }

        // Extract text lines
        const textLines = container ? container.innerText.split('\n').map(l => l.trim()).filter(Boolean) : [];

        items.push({
          name: a.innerText.trim(),
          href: href,
          lines: textLines
        });
      }
    }
  }
  return items;
});

console.log(`Found ${schools.length} schools total.`);
schools.slice(0, 25).forEach((s, idx) => {
  console.log(`${idx + 1}: ${s.name} - Lines: ${JSON.stringify(s.lines.slice(0, 5))}`);
