const tabId = 845789484;

const schoolList = await browserjs(tabId, () => {
  // Let's find all elements that have class or test-id related to school headings
  // Or find all h3 elements with school names
  const headings = Array.from(document.querySelectorAll('h3'));
  const results = [];

  headings.forEach(h => {
    const text = h.innerText.trim();
    if (!text || text.includes('Rankings') || text.includes('Photos') || text.includes('Search')) return;

    // Find surrounding text: previous sibling, parent, next sibling
    let parent = h.parentElement;
    while (parent && parent.innerText.length < 150 && parent.parentElement && parent.parentElement.tagName !== 'BODY') {
      parent = parent.parentElement;
    }

    // Check if it has a rank like #1, #2, etc.
    const parentText = parent ? parent.innerText : '';
    const rankMatch = parentText.match(/#(\d+)/);
    // Also look for City, State like "Stanford, CA" or "Chicago , IL"
    const locationMatch = parentText.match(/([A-Z][a-zA-Z\s.-]+)\s*,\s*([A-Z]{2})/);

    results.push({
      name: text,
      rank: rankMatch ? rankMatch[1] : null,
      location: locationMatch ? `${locationMatch[1].trim()}, ${locationMatch[2]}` : null,
      fullTextSnippet: parentText.slice(0, 250).replace(/\n+/g, ' | ')
    });
  });

  return results;
});

console.log(`Found ${schoolList.length} potential schools:`);
schoolList.forEach((s, i) => console.log(`${i+1}: Rank ${s.rank} | ${s.name} | ${s.location}`));

