const tabId = 845789533;
const details = await browserjs(tabId, () => {
  const text = document.body.innerText;

  // Search for fee and standardized test
  const feeMatch = text.match(/fee.*?(\$\d+)/i) || text.match(/(\$\d+).*?fee/i);
  const testMatch = text.match(/(LSAT|GRE|standardized test)[\s\S]{0,300}/i);

  return {
    feeSnippet: feeMatch ? feeMatch[0] : null,
    testSnippet: testMatch ? testMatch[0] : null,
    fullText: text
  };
});

console.log("Fee snippet:", details.feeSnippet);
// Look for fee occurrences
const matches = details.fullText.match(/.{0,50}\$\d+.{0,50}/g);
console.log("Dollar matches:", matches);

