const tabId = 845789539;

const details = await browserjs(tabId, () => {
  // Let's get the text of headings and their subsequent sibling paragraphs/divs
  const headings = Array.from(document.querySelectorAll('h2, h3, h4, summary, dt, button'));
  const list = [];
  headings.forEach(h => {
    let text = h.innerText.trim();
    let siblingText = '';
    let curr = h.nextElementSibling;
    let count = 0;
    while (curr && count < 5) {
      siblingText += ' ' + curr.innerText.trim();
      curr = curr.nextElementSibling;
      count++;
    }
    list.push({ heading: text, content: siblingText.slice(0, 500) });
  });
  return list;
});

