  d.heading.includes('Checklist') || 
  d.heading.includes('Standardized') ||
  d.heading.includes('Test') ||
  d.heading.includes('Fee')
);

console.log("Penn Carey relevant sections:\n", JSON.stringify(relevant, null, 2));

