const tabId = 845789544;

const qa = await browserjs(tabId, () => {
  const headings = Array.from(document.querySelectorAll('h3, h4, summary'));
  const results = [];
  headings.forEach(h => {
    const text = h.innerText.trim();
    if (text.includes('deadline') || text.includes('submit') || text.includes('fee') || text.includes('LSAT and GRE') || text.includes('prefer one test') || text.includes('both the LSAT')) {
      let sibling = h.nextElementSibling;
      let ans = '';
      while (sibling && !['H2', 'H3', 'H4'].includes(sibling.tagName)) {
        ans += ' ' + sibling.innerText.trim();
        sibling = sibling.nextElementSibling;
      }
      results.push({ q: text, a: ans.trim().slice(0, 500) });
    }
  });
  return results;
});

console.log("Duke QA:", JSON.stringify(qa, null, 2));

