const feeInfo = await browserjs(tabId, () => {
  const text = document.body.innerHTML;
  const matches = [];
  const regex = /fee/gi;
  let match;
  while ((match = regex.exec(text)) !== null) {
    matches.push(text.slice(Math.max(0, match.index - 50), Math.min(text.length, match.index + 100)));
  }
  return matches;
});

console.log(`Found ${feeInfo.length} fee matches:`);
feeInfo.slice(0, 10).forEach(m => console.log(m.replace(/\n+/g, ' ')));

