await tool.navigate({ tabId, url: "https://www.law.northwestern.edu/admissions/applying/#jd" });
await tool.wait_for({ tabId, condition: "load_state", value: "load" });

const jdSection = await browserjs(tabId, () => {
  const el = document.getElementById('jd') || document.querySelector('a[name="jd"]');
  if (el) {
    let p = el.parentElement;
    for (let i = 0; i < 3; i++) if (p && p.parentElement) p = p.parentElement;
    return p.innerText.slice(0, 3000);
  }
  // Let's find any text containing "Apply to the JD Program"
  const link = Array.from(document.querySelectorAll('a')).find(a => a.innerText.includes('Apply to the JD Program'));
  if (link) {
    return { href: link.href, outer: link.parentElement.outerHTML };
  }
  return document.body.innerText.slice(0, 2000);
});

console.log("Northwestern JD details:\n", JSON.stringify(jdSection, null, 2));

